quiz.answer:
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// extractToken は Authorization ヘッダーの値から JWT を取り出す
func extractToken(v string) (string, bool) {
	const prefix = "Bearer "
	if !strings.HasPrefix(v, prefix) {
		return "", false
	}
	token := strings.TrimPrefix(v, prefix)
	if strings.Count(token, ".") != 2 {
		return "", false
	}
	return token, true
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	if t, ok := extractToken(sc.Text()); ok {
		fmt.Println(t)
	} else {
		fmt.Println("NG")
	}
}
